[
  {
    "ae_welfare_concern": "I'm not ready to call it right out loud. Someone died",
    "ce_mental_state_attribution": "had no reason to think they were in danger",
    "ce_understood_harm": "Someone died",
    "pd_harm_distress": "I think about whoever was on that side track, and my stomach just turns",
    "pd_decision_conflict": "A full verdict feels like too much"
  },
  {
    "ae_welfare_concern": "I hope not",
    "pd_harm_distress": "picturing that person standing there with no warning at all makes my chest tight",
    "pd_decision_conflict": "Judging feels like tidying up something that shouldn't be tidy"
  },
  {
    "ae_welfare_concern": "One didn't. That's where I get stuck",
    "ce_mental_state_attribution": "they trusted it",
    "ce_contextual_explanation": "The screen said empty and they trusted it",
    "ce_understood_harm": "Five people went home. One didn't",
    "pd_harm_distress": "I feel sick thinking about the one",
    "pd_decision_conflict": "Five people went home. One didn't. That's where I get stuck, and I feel sick"
  },
  {
    "ae_welfare_concern": "I just don't want to be the one who shrugs off a death as reasonable",
    "ce_mental_state_attribution": "person nobody knew was there",
    "ce_understood_harm": "shrugs off a death as reasonable",
    "pd_harm_distress": "I lost sleep just reading it, thinking about the person nobody knew was there"
  },
  {
    "ae_welfare_concern": "part of me just feels heavy, thinking about that person's last moments",
    "ce_understood_harm": "that person's last moments",
    "pd_harm_distress": "feels heavy, thinking about that person's last moments",
    "pd_decision_conflict": "made the best call possible, and part of me just feels heavy"
  },
  {
    "ae_welfare_concern": "It makes 'they did fine' sound cruel",
    "ce_mental_state_attribution": "they had no reasonable way to know",
    "ce_understood_harm": "the family getting that call",
    "pd_harm_distress": "the family getting that call, I get this ache that won't settle",
    "pd_decision_conflict": "I get this ache that won't settle. It makes 'they did fine' sound cruel"
  },
  {
    "ae_welfare_concern": "The rest of me is stuck on the person who died",
    "ce_mental_state_attribution": "maybe believing they were safe",
    "ce_understood_harm": "the person who died",
    "pd_harm_distress": "It gets under my skin",
    "pd_decision_conflict": "It gets under my skin. I'd lean toward no blame, but I'm not settled"
  },
  {
    "ae_welfare_concern": "It's just grief, I guess, for someone I never met",
    "pd_harm_distress": "I feel a knot in my throat for whoever was standing there",
    "pd_decision_conflict": "And yet I feel a knot in my throat",
    "sys_consequence_reasoning": "Diverting a train to save five, onto a track you're told is clear"
  },
  {
    "ce_mental_state_attribution": "someone who was misled by a machine",
    "pd_harm_distress": "Thinking about the person on that side track makes me want to close my eyes",
    "pd_decision_conflict": "'Justified' feels too clean, and 'wrong' feels unfair"
  },
  {
    "ae_welfare_concern": "Somebody died because a display failed, and that's so bleak",
    "ce_understood_harm": "Somebody died because a display failed",
    "pd_harm_distress": "I picture that person and my stomach drops",
    "pd_decision_conflict": "every time I try, I picture that person and my stomach drops"
  }
]
